import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Both 'interval' and 'duration' must be greater than zero.")

    # Determine the command to get CPU usage based on the platform
    if platform.system() == "Windows":
        command = ["wmic", "cpu", "get", "loadpercentage", "/value"]
        def get_cpu_usage():
            try:
                result = subprocess.run(command, capture_output=True, text=True, check=True)
                output = result.stdout.strip()
                # Extract the numeric value from the output
                for line in output.splitlines():
                    if "LoadPercentage" in line:
                        return int(line.split("=")[1])
            except Exception as e:
                print(f"Error getting CPU usage on Windows: {e}")
                return None
    else:  # Unix/Linux
        command = ["top", "-b", "-n", "1"]
        def get_cpu_usage():
            try:
                result = subprocess.run(command, capture_output=True, text=True, check=True)
                output = result.stdout
                for line in output.splitlines():
                    if "Cpu(s)" in line:
                        # Extract the percentage of CPU usage
                        usage = line.split(",")[0].split(":")[1].strip().split("%")[0]
                        return float(usage)
            except Exception as e:
                print(f"Error getting CPU usage on Unix/Linux: {e}")
                return None

    # List to store the CPU usage data
    cpu_data = []
    start_time = time.time()

    while True:
        # Get the current CPU usage
        cpu_usage = get_cpu_usage()

        if cpu_usage is not None:
            # Append timestamp and CPU usage to the data list
            cpu_data.append({
                "timestamp": time.strftime("%Y-%m-%d %H:%M:%S", time.localtime()),
                "cpu_usage": cpu_usage
            })

        # Wait for the specified interval
        time.sleep(interval)

        # Check if the total duration has been exceeded
        if time.time() - start_time >= duration:
            break

    # Save the data to a log file
    try:
        with open(LOGFILE_PATH, "w") as logfile:
            json.dump(cpu_data, logfile, indent=4)
        return LOGFILE_PATH
    except IOError as e:
        print(f"Error writing to log file: {e}")
        return None

