            # Construct the FTP URL for the file
            ftp_url = f"ftp://{ftp_user}:{ftp_password}@{ftp_server}{ftp_dir}/{filename}"

            # Use wget to download the file
            result = subprocess.run(['wget', ftp_url], capture_output=True, text=True)

            if result.returncode == 0:
                downloaded_files.append(filename)
            else:
                print(f"Failed to download file {filename}: {result.stderr}")
        except Exception as e:
            print(f"Error occurred while downloading file {filename}: {str(e)}")

    return downloaded_files

