import subprocess
import os
import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    """
    Compress all files in the specified source folder using gzip and move the compressed files 
    to the destination folder. Runs as a background process.

    Parameters:
    src_folder (str): Path to the source folder containing files to compress.
    dst_folder (str): Path to the destination folder where compressed files will be moved.

    Returns:
    dict: A dictionary containing:
        'success' (bool): Indicates if all files were compressed and moved successfully.
        'message' (str): Descriptive message about the operation's result.
        'failed_files' (list): List of filenames that failed to compress or move.
    """
    # Ensure source and destination folders exist
    if not os.path.exists(src_folder):
        return {'success': False, 'message': f"Source folder '{src_folder}' does not exist.", 'failed_files': []}
    if not os.path.exists(dst_folder):
        try:
            os.makedirs(dst_folder)
